module TopModule(
	input wire clk  ,
	input wire rst  ,
	input wire d1 ,
	input wire d2 ,
	input wire sel ,

	output reg out1,
	output reg out2,
	output reg out3
);
//*************code***********//

    localparam S0      = 4'd0,
               S05     = 4'd1,
               S1      = 4'd2,
               S15     = 4'd3,
               S2      = 4'd4,
               S25     = 4'd5,
               S3      = 4'd6,
               DISP1   = 4'd7,
               DISP1_3 = 4'd8,
               DISP2   = 4'd9,
               DISP2_3 = 4'd10;

    reg [3:0] state, next_state;

    always @(posedge clk or negedge rst) begin
        if (!rst)
            state <= S0;
        else
            state <= next_state;
    end

    always @(*) begin
        next_state = state;
        case (state)
            DISP1, DISP1_3, DISP2, DISP2_3: begin
                if (d1)
                    next_state = S05;
                else if (d2)
                    next_state = S1;
                else
                    next_state = S0;
            end
            S0: begin
                if (d1) next_state = S05;
                else if (d2) next_state = S1;
                else next_state = S0;
            end
            S05: begin
                if (d1) next_state = S1;
                else if (d2) next_state = S15;
                else next_state = S05;
            end
            S1: begin
                if (d1) next_state = S15;
                else if (d2) next_state = S2;
                else next_state = S1;
            end
            S15: begin
                if (sel == 0) begin
                    next_state = DISP1;
                end else begin
                    if (d1) next_state = S2;
                    else if (d2) next_state = S25;
                    else next_state = S15;
                end
            end
            S2: begin
                if (sel == 0) begin
                    next_state = DISP1_3;
                end else begin
                    if (d1) next_state = S25;
                    else if (d2) next_state = S3;
                    else next_state = S2;
                end
            end
            S25: begin
                if (sel == 1) begin
                    next_state = DISP2;
                end else begin
                    if (d1) next_state = S3;
                    else if (d2) next_state = S3;
                    else next_state = S25;
                end
            end
            S3: begin
                if (sel == 1) begin
                    next_state = DISP2_3;
                end else begin
                    next_state = DISP1_3;
                end
            end
            default: next_state = S0;
        endcase
    end

    always @(*) begin
        out1 = 0;
        out2 = 0;
        out3 = 0;
        case (state)
            DISP1:   out1 = 1;
            DISP1_3: begin out1 = 1; out3 = 1; end
            DISP2:   out2 = 1;
            DISP2_3: begin out2 = 1; out3 = 1; end
            default: begin out1 = 0; out2 = 0; out3 = 0; end
        endcase
    end
//*************code***********//
endmodule
